    { title: "White Pine Logging: A Background (Michigan State)", url: "https://project.geo.msu.edu/geogmich/loggingbackgrd.html" },
    { title: "Balloon Framing: Technology That Changed Chicago (Chicago Public Library)", url: "https://www.chipublib.org/blogs/post/technology-that-changed-chicago-balloon-framing/" },
    { title: "Nominal Versus Actual: A History of the 2x4 (Harvard Design Magazine)", url: "https://www.harvarddesignmagazine.org/articles/nominal-versus-actual-a-history-of-the-2x4/" },
    { title: "An Early Reforestation Experiment (Weyerhaeuser)", url: "https://prd.weyerhaeuser.com/story/history-early-reforestation-experiment/" }
